-  describe('userIdHook', function() {
-    beforeEach(function() {
+  describe('userIdHook', function () {
+    beforeEach(function () {
       logWarnSpy = sinon.spy(utils, 'logWarn');
       nextFnSpy = sinon.spy();
     });
